={{
(() => {
  let allScenes = [];
  try { allScenes = $('Merge Hybrid Scenes').all(); } catch(e) {}
  if (!allScenes || allScenes.length === 0) {
    allScenes = $input.all();
  }

  const VOICE_MAP = {
    adam: 'pNInz6obpgDQGcFmaJgB',
    laura: 'FGY2WhTYpPnrIDTdsKH5',
    liam: 'TX3LPaxmHKxFdv7VOQHJ',
    brian: 'nPczCjzI2devNBz1zQrb',
    george: 'JBFqnCBsd6RMkjVDRZzb',
    daniel: 'onwK4e9ZLuTAKqWW03F9',
    lily: 'pFZP5JQG7iQjIQuC4Bku',
    sarah: 'EXAVITQu4vr4xnSDxMaL',
    charlie: 'IKne3meq5aSn9XLyUdCD',
    callum: 'N2lVS1w4EtoT3dr4eOWO',
    river: 'SAz9YHcvj6GT2YYXdXww',
    will: 'bIHbv24MWmeRgasZH58o',
    jessica: 'cgSgspJ2msm6clMCkdW9',
    eric: 'cjVigY5qzO86Huf0OWal',
    chris: 'iP95p4xoKVk53GoZ742B',
    matilda: 'XrExE9yKIg1WjnnlVkGX',
    charlotte: 'XB0fDUnXU5powFXDhCwa',
    alice: 'Xb7hH8MSUJpSbSDYk0k2',
    bill: 'pqHfZKP75CvOlQylNhV4'
  };

  const batchScenes = allScenes
    .sort((a, b) => (a.json?.sceneNumber || 0) - (b.json?.sceneNumber || 0))
    .slice(0, 2)
    .map((s) => {
      let voiceElId = 'pNInz6obpgDQGcFmaJgB';
      let speed = 1.20;
      try {
        const custom = {};
        let site = {};
        try { site = $('Filter: My Chat Only').first().json || {}; } catch(e2) {}
        const rawEl = (custom.elevenLabsVoiceId || site.elevenLabsVoiceId || '').trim();
        const rawV = (custom.voiceId || site.voiceId || '').trim().toLowerCase();
        if (rawEl && rawEl.length > 15) {
          voiceElId = rawEl;
        } else if (rawEl && VOICE_MAP[rawEl.toLowerCase()]) {
          voiceElId = VOICE_MAP[rawEl.toLowerCase()];
        } else if (rawV && VOICE_MAP[rawV]) {
          voiceElId = VOICE_MAP[rawV];
        } else if (rawV && rawV.length > 15) {
          voiceElId = rawV;
        }

        const rawSpeed = custom.voiceSpeed !== undefined ? custom.voiceSpeed : site.voiceSpeed;
        if (rawSpeed !== undefined) {
          const numSpeed = Number(rawSpeed);
          if (isFinite(numSpeed) && numSpeed > 0) speed = Math.max(0.5, Math.min(4, numSpeed));
        }
      } catch(e) {}
      return {
        duration: -1,
        elements: [
          {
            type: 'voice',
            voice: voiceElId,
            text: s.json.voiceoverText || '',
            model: 'elevenlabs',
            speed: speed
          }
        ]
      };
    });

  return JSON.stringify({
    resolution: 'preview',
    quality: 'low',
    scenes: batchScenes
  });
})()
}}

