={{ (() => {
  const REF = 'Use Reference Image 1 as the visual character reference. Keep the same character, face or sacred-figure light, outfit and colours in every shot. ';
  let anchor = String($json.anchorImageUrl || '').trim();
  if (!anchor) { try { anchor = String($('Split Scenes').first().json.anchorImageUrl || '').trim(); } catch (e) {} }
  const input = {
    prompt: (anchor ? REF : '') + String($json.videoPrompt || ''),
    aspect_ratio: '9:16',
