const mergeData = $input.first().json;
const urlMap = {};
const keys = Object.keys(mergeData);

keys.forEach(k => {
  if (k === 'sceneNumber' || k.match(/^sceneNumber_\d+$/)) {
    const sceneNum = parseInt(mergeData[k], 10);
    let urlKey;
    if (k === 'sceneNumber') {
      urlKey = 'videoUrl';
    } else {
      const suffix = k.slice('sceneNumber'.length);
      urlKey = 'videoUrl' + suffix;
    }

    let finalUrl = mergeData[urlKey] || '';
    if (Array.isArray(finalUrl)) finalUrl = finalUrl[0];
    if (sceneNum && finalUrl) urlMap[sceneNum] = finalUrl;
  }
});

const staticData = $getWorkflowStaticData('global');
const script = staticData.islamicFullScript || {};
const fullScenes = script.scenes || [];

if (!fullScenes || fullScenes.length === 0) {
