// ── R10-A: httpFetch shim — the n8n Code sandbox has no global fetch API.
// Backed by this.helpers.httpRequest. Mimics only the parts of the
// HTTP client API this node uses: .ok .status .headers.get() .json() .text()
const helpers = this.helpers;
async function httpFetch(url, opts = {}) {
  const reqOpts = {
    method: String(opts.method || 'GET').toUpperCase(),
    url,
    headers: opts.headers || {},
    json: false,
    returnFullResponse: true,
    timeout: opts.timeout || 300000
  };
  if (opts.body !== undefined && opts.body !== null) reqOpts.body = opts.body;

  let statusCode = 0;
  let rawHeaders = {};
  let rawBody = '';
  try {
    const r = await helpers.httpRequest(reqOpts);
    statusCode = r.statusCode || 200;
    rawHeaders = r.headers || {};
    rawBody = r.body;
  } catch (err) {
    const resp = (err && (err.response || (err.cause && err.cause.response))) || {};
    statusCode = Number(resp.status || resp.statusCode || err.statusCode || err.httpCode || 0) || 0;
    rawHeaders = resp.headers || {};
    rawBody = resp.data !== undefined ? resp.data
            : (err.description || err.message || String(err));
  }

  const asText = () => {
    if (typeof rawBody === 'string') return rawBody;
    if (rawBody === undefined || rawBody === null) return '';
    if (Buffer.isBuffer(rawBody)) return rawBody.toString('utf8');
    try { return JSON.stringify(rawBody); } catch (e) { return String(rawBody); }
  };

  return {
    ok: statusCode >= 200 && statusCode < 300,
    status: statusCode,
    statusText: '',
    headers: {
      get: (name) => {
        const want = String(name).toLowerCase();
        const keys = Object.keys(rawHeaders || {});
        for (let i = 0; i < keys.length; i++) {
          if (keys[i].toLowerCase() === want) return rawHeaders[keys[i]];
        }
        return null;
      }
    },
    text: async () => asText(),
    json: async () => {
      if (rawBody && typeof rawBody === 'object' && !Buffer.isBuffer(rawBody)) return rawBody;
      try { return JSON.parse(asText()); } catch (e) { return {}; }
    }
  };
}

// Dynamic Google Sheets Logger: Logs video production row directly to User's Connected Spreadsheet
const item = $input.first()?.json || {};
let chatCtx = {};
try { chatCtx = $('Filter: My Chat Only').first().json || {}; } catch(e) {}
let splitScenes = {};
try { splitScenes = $('Split Scenes').first().json || {}; } catch(e) {}
let parseTopic = {};
try { parseTopic = $('Parse Topic Analyzer Output').first().json || {}; } catch(e) {}
let parseStrategy = {};
try { parseStrategy = $('Parse Strategy Output').first().json || {}; } catch(e) {}
let videoUrl = '';
try { videoUrl = $('Status = Done?').first().json?.movie?.url || ''; } catch(e) {}

let userSheetToken = chatCtx.userSheetAccessToken;
const userSpreadsheetId = chatCtx.userSpreadsheetId;
const userSheetName = chatCtx.userSheetName || 'Production Log';
const autoLogEnabled = chatCtx.autoLogToSheet !== false;
const youtubeLink = item.uploadId ? ('https://youtube.com/shorts/' + item.uploadId) : (item.url || '');

let sheetError = null;
let sheetAppended = false;

if (userSpreadsheetId && autoLogEnabled) {
  // Pre-append token refresh
  if (chatCtx.threadId) {
    try {
      const refreshRes = await httpFetch('https://bangai.netlify.app/.netlify/functions/refresh-upload-token', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-webhook-secret': 's-vshorts-sec-9a8b7c6d5e4f3a2b1c0'
        },
        body: JSON.stringify({
          threadId: chatCtx.threadId,
          channelId: userSpreadsheetId,
          scope: 'sheets'
        })
      });
      if (refreshRes.ok) {
        const refreshData = await refreshRes.json();
        if (refreshData.accessToken) userSheetToken = refreshData.accessToken;
      }
    } catch (e) {}
  }

  if (userSheetToken) {
    try {
      const range = encodeURIComponent(userSheetName || 'Sheet1');
      const topicText = parseTopic.specificTopic || parseStrategy.suggestedTitle || chatCtx.prompt || chatCtx.rawUserInput || 'World Mysteries & Paranormal';
      const rowValues = [
        new Date().toISOString().replace('T', ' ').substring(0, 16),
        parseStrategy.suggestedTitle || splitScenes.title || topicText,
        topicText,
        (parseStrategy.storyBrief || splitScenes.storyBrief || '').toString().slice(0, 480),
        parseStrategy.mainCharacterHint || '',
        parseStrategy.visualStyle || 'Dark Cinematic Mystery',
        parseStrategy.language || 'English',
        item.uploadId ? 'Uploaded to YouTube' : 'Video Rendered',
        videoUrl,
        youtubeLink
      ];

      const sheetRes = await httpFetch('https://sheets.googleapis.com/v4/spreadsheets/' + userSpreadsheetId + '/values/' + range + ':append?valueInputOption=USER_ENTERED', {
        method: 'POST',
        headers: {
          'Authorization': 'Bearer ' + userSheetToken,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          range: userSheetName || 'Sheet1',
          majorDimension: 'ROWS',
          values: [rowValues]
        })
      });

      if (!sheetRes.ok) {
        const errTxt = await sheetRes.text();
        console.warn('[n8n] Google Sheets API error:', errTxt);
        sheetError = 'Google Sheets error: ' + errTxt;
      }
      if (sheetRes.ok) sheetAppended = true;
    } catch (err) {
      console.warn('[n8n] Error appending to user Google Sheet:', err.message);
      sheetError = err.message;
    }
  }
}

return [{
  json: {
    ...item,
    sheetLogged: sheetAppended,
    sheetLogSkipped: (!sheetAppended && !sheetError) ? true : undefined,
    error: sheetError || undefined
  }
}];

