// Rotate Zvid Key with 3-Part Voiceovers & Method 1 Speed Retiming
const zvidConfigNode = $('Config: Zvid Master').first().json;
const keys = zvidConfigNode.keys || zvidConfigNode.zvidApiKeys || [];

if (!keys || keys.length === 0) {
  throw new Error("No Zvid.io API keys configured in 'Config: Zvid Master' node.");
