}

const currentKeyIndex = staticData.lastZvidKeyIndex;
const currentKey = keys[currentKeyIndex];

let scenes = [];
try {
  scenes = $('Merge Hybrid Scenes').all();
} catch (e) {}

if (!scenes || scenes.length === 0) {
  scenes = $input.all();
}

scenes = scenes.sort((a, b) => (a.json?.sceneNumber || 0) - (b.json?.sceneNumber || 0));

// Extract converted MP3 files from CloudConvert
let ccTasks = [];
try {
  const allCcRuns = $('Convert Dual Voice to Pure MP3 (CloudConvert)').all();
  for (let i = allCcRuns.length - 1; i >= 0; i--) {
    if (allCcRuns[i]?.json?.data?.tasks && allCcRuns[i].json.data.tasks.length > 0) {
      ccTasks = allCcRuns[i].json.data.tasks;
      break;
    }
  }
} catch (e) {
  try {
    ccTasks = $('Convert Dual Voice to Pure MP3 (CloudConvert)').first().json.data?.tasks || [];
  } catch(e2) {}
}

const part1File = ccTasks.find(t => t.name === 'export-part1')?.result?.files?.[0]?.url;
const part2File = ccTasks.find(t => t.name === 'export-part2')?.result?.files?.[0]?.url;
const part3File = ccTasks.find(t => t.name === 'export-part3')?.result?.files?.[0]?.url;

// Retrieve exact voiceover part durations from JSON2Video
let p1Dur = 30;
try { p1Dur = Number($('Poll Voiceover Part 1').first().json?.movie?.duration) || 30; } catch(e) {}
let p2Dur = 30;
try { p2Dur = Number($('Poll Voiceover Part 2').first().json?.movie?.duration) || 30; } catch(e) {}
let p3Dur = 15;
try { p3Dur = Number($('Poll Voiceover Part 3').first().json?.movie?.duration) || 15; } catch(e) {}

// Calculate proportional scene speech durations for each part
const text1 = (scenes[0]?.json?.voiceoverText || '').trim();
const text2 = (scenes[1]?.json?.voiceoverText || '').trim();
const text3 = (scenes[2]?.json?.voiceoverText || '').trim();
const text4 = (scenes[3]?.json?.voiceoverText || '').trim();
const text5 = (scenes[4]?.json?.voiceoverText || '').trim();

// Part 1: Scenes 1 & 2
const len1 = text1.length || 1;
const len2 = text2.length || 1;
const w1 = len1 / (len1 + len2);
const d1 = Number((p1Dur * w1).toFixed(2));
const d2 = Number((p1Dur - d1).toFixed(2));

// Part 2: Scenes 3 & 4
const len3 = text3.length || 1;
const len4 = text4.length || 1;
const w3 = len3 / (len3 + len4);
const d3 = Number((p2Dur * w3).toFixed(2));
const d4 = Number((p2Dur - d3).toFixed(2));

// Part 3: Scene 5
const d5 = Number(p3Dur.toFixed(2));

const sceneDurations = [d1, d2, d3, d4, d5];
const totalDuration = Number((d1 + d2 + d3 + d4 + d5).toFixed(2));

// ── Method 1: Speed Retiming & Dynamic Visual Timeline ──
let currentVisualStart = 0;
const visuals = scenes.slice(0, 5).map((s, idx) => {
  const dur = sceneDurations[idx];
  const enter = Number(currentVisualStart.toFixed(2));
  const exit = Number((currentVisualStart + dur).toFixed(2));
  currentVisualStart = exit;

  // Kie.ai clips are rendered at 15.04s. Speed = 15.04 / dur perfectly retimes video to speech!
  const speed = Number(Math.max(0.2, Math.min(5.0, 15.04 / dur)).toFixed(3));

  const v = {
    type: 'VIDEO',
    id: 'scene' + (idx + 1),
    src: s.json.url || s.json.videoUrl,
    resize: 'cover',
    volume: 0,
    speed: speed,
    enterBegin: enter,
    exitEnd: exit
  };
  if (idx < 4) {
    v.transition = 'fade';
    v.transitionDuration = 0.5;
    v.transitionId = 'scene' + (idx + 2);
  }
  return v;
});

// Dynamic Settings Extraction from Website / Approvals
let site = {};
try { site = $('Filter: My Chat Only').first().json || {}; } catch(e) {}
const userCustom = {};

// 1. Voice Volume
const rawVoiceVol = userCustom.voiceVolume !== undefined ? userCustom.voiceVolume : site.voiceVolume;
const numVoiceVol = Number(rawVoiceVol);
const safeVoiceVol = isFinite(numVoiceVol) ? Math.max(0, Math.min(2.0, numVoiceVol)) : 1.0;

// 2. Music Track & Volume
const MUSIC_MAP = {
  synth: 'https://bangai.netlify.app/music/synth.mp3',
  ambient: 'https://bangai.netlify.app/music/ambient.mp3',
  mystery2: 'https://bangai.netlify.app/music/mystery2.mp3',
  indian: 'https://bangai.netlify.app/music/indian.mp3',
  action: 'https://bangai.netlify.app/music/action.mp3',
  piano: 'https://bangai.netlify.app/music/piano.mp3',
  playful: 'https://bangai.netlify.app/music/playful.mp3',
  epic: 'https://bangai.netlify.app/music/epic.mp3'
};
const DEFAULT_BG_MUSIC = 'https://bangai.netlify.app/music/mystery2.mp3';

const chosenMusicId = String(userCustom.musicId || site.musicId || 'mystery2').toLowerCase();
let bgMusicUrl = userCustom.musicTrackUrl || site.musicTrackUrl || MUSIC_MAP[chosenMusicId] || '';
if (!bgMusicUrl && chosenMusicId !== 'none') {
  bgMusicUrl = DEFAULT_BG_MUSIC;
}

const rawMusicVol = userCustom.musicVolume !== undefined ? userCustom.musicVolume : site.musicVolume;
const numMusicVol = Number(rawMusicVol);
const safeMusicVol = isFinite(numMusicVol) ? Math.max(0, Math.min(0.4, numMusicVol)) : 0.08;

const audios = [
  {
    src: part1File,
    volume: safeVoiceVol,
    enter: 0,
    exit: Number((d1 + d2).toFixed(2))
  },
  {
    src: part2File,
    volume: safeVoiceVol,
    enter: Number((d1 + d2).toFixed(2)),
    exit: Number((d1 + d2 + d3 + d4).toFixed(2))
  },
  {
    src: part3File,
    volume: safeVoiceVol,
    enter: Number((d1 + d2 + d3 + d4).toFixed(2)),
    exit: totalDuration
  }
];

if (bgMusicUrl && chosenMusicId !== 'none' && safeMusicVol > 0) {
  audios.push({
    src: bgMusicUrl,
    volume: safeMusicVol,
    enter: 0,
    exit: totalDuration
  });
}

// ── Smart Paced & Real-Time Synchronized Subtitle Captions ──
const rawSpeed = userCustom.voiceSpeed !== undefined ? userCustom.voiceSpeed : site.voiceSpeed;
let voiceSpeed = 1.20;
if (rawSpeed !== undefined) {
  const numSpeed = Number(rawSpeed);
  if (isFinite(numSpeed) && numSpeed > 0) voiceSpeed = Math.max(0.5, Math.min(4.0, numSpeed));
}

const lang = String(site.language || '').toLowerCase();
const allVoText = scenes.map(s => s.json?.voiceoverText || '').join(' ');
const hasDevanagari = /[\u0900-\u097F]/.test(allVoText) || lang.includes('hindi') || lang.includes('hinglish');

const captions = [];
let sceneStartCursor = 0;

scenes.slice(0, 5).forEach((s, idx) => {
  const dur = sceneDurations[idx];
  const rawText = (s.json?.voiceoverText || '').trim();
  if (!rawText) {
    sceneStartCursor += dur;
    return;
  }

  // Segment text into natural rhythmic subtitle chunks (4-8 words each)
  const rawSentences = rawText.split(/(?<=[।!?\.\n])\s+/).map(t => t.trim()).filter(Boolean);
  const chunks = [];
  for (const sent of rawSentences) {
    const words = sent.split(/\s+/);
    if (words.length > 8 && /[,;，、]/.test(sent)) {
      const subParts = sent.split(/(?<=[,;，、])\s+/).map(t => t.trim()).filter(Boolean);
      chunks.push(...subParts);
    } else if (words.length > 10) {
      const mid = Math.ceil(words.length / 2);
      chunks.push(words.slice(0, mid).join(' '));
      chunks.push(words.slice(mid).join(' '));
    } else {
      chunks.push(sent);
    }
  }

  if (chunks.length === 0) chunks.push(rawText);

  const totalWords = rawText.split(/\s+/).length;
  const totalChars = rawText.length;

  const pauseBetween = 0.08;
  const totalPauseTime = (chunks.length - 1) * pauseBetween;
  const activeSpeechTime = Math.max(2.0, (dur * 0.95) - totalPauseTime);

  const chunkWeights = chunks.map(c => {
    const cWords = c.split(/\s+/).length;
    const cChars = c.length;
    return (cWords / totalWords) * 0.5 + (cChars / totalChars) * 0.5;
  });

  let cursor = sceneStartCursor;
  chunks.forEach((chunk, cIdx) => {
    const chunkDur = activeSpeechTime * chunkWeights[cIdx];
    const start = Number(cursor.toFixed(2));
    const end = Number((cursor + chunkDur).toFixed(2));
    captions.push({
      start: start,
      end: end,
      text: chunk
    });
    cursor = end + pauseBetween;
  });

  sceneStartCursor += dur;
});

// Dynamic Subtitle Configuration from User Settings
const rawSubs = userCustom.subtitleSettings || site.subtitleSettings || {};

let resolvedFontFamily = rawSubs.fontFamily || (rawSubs.font && rawSubs.font.family) || (hasDevanagari ? 'Noto Sans Devanagari' : 'Montserrat');
if (hasDevanagari && ['Montserrat', 'Inter', 'Bebas Neue', 'Luckiest Guy', 'Bangers', 'Oswald', 'Permanent Marker'].includes(resolvedFontFamily)) {
  resolvedFontFamily = 'Noto Sans Devanagari';
