const subStyle = String(rawSubs.style || rawSubs.presetId || '').toLowerCase();
const hasBox = !!(rawSubs.boxColor || subStyle.includes('box'));
const isOneWord = subStyle.includes('one-word') || rawSubs.maxWordsPerLine === 1;

let animationType = 'karaoke';
if (hasBox) {
  animationType = 'highlight';
} else if (isOneWord) {
  animationType = 'one-word';
}

const activeWordColor = rawSubs.wordColor || (rawSubs.activeWord && rawSubs.activeWord.color) || '#FFE500';
const activeWordObj = { color: activeWordColor };
if (hasBox) {
  activeWordObj.background = rawSubs.boxColor || '#16A34A';
