else if (rawPos.includes('center') && !rawPos.includes('bottom') && !rawPos.includes('mid')) zvidPosition = 'center';

const payload = {
  name: 'short-assembly-retimed',
  duration: totalDuration,
  resolution: 'youtube-short',
  frameRate: 30,
  backgroundColor: '#000000',
  outputFormat: 'mp4',
  visuals: visuals,
  audios: audios,
  subtitle: {
    captions: captions,
    animation: animationType,
    activeWord: activeWordObj,
    font: {
      family: resolvedFontFamily,
      size: Number(rawSubs.fontSize) || 72,
      color: rawSubs.lineColor || (rawSubs.font && rawSubs.font.color) || '#FFFFFF',
      bold: true
    },
    stroke: {
      color: rawSubs.outlineColor || (rawSubs.stroke && rawSubs.stroke.color) || '#000000',
      width: Number(rawSubs.outlineWidth) || (rawSubs.stroke && rawSubs.stroke.width) || 10
    },
    position: zvidPosition,
    maxWordsPerLine: isOneWord ? 1 : (Number(rawSubs.maxWordsPerLine) || 3)
  }
};

