  let rawBody = '';
  try {
    const r = await helpers.httpRequest(reqOpts);
    statusCode = r.statusCode || 200;
    rawHeaders = r.headers || {};
    rawBody = r.body;
  } catch (err) {
    const resp = (err && (err.response || (err.cause && err.cause.response))) || {};
    statusCode = Number(resp.status || resp.statusCode || err.statusCode || 0) || 0;
    rawHeaders = resp.headers || {};
    rawBody = resp.data !== undefined ? resp.data : (err.message || String(err));
  }
  const asText = () => typeof rawBody === 'string' ? rawBody : (Buffer.isBuffer(rawBody) ? rawBody.toString('utf8') : JSON.stringify(rawBody || ''));
  return {
    ok: statusCode >= 200 && statusCode < 300,
    status: statusCode,
    headers: {
      get: (name) => {
        const want = String(name).toLowerCase();
        for (const k of Object.keys(rawHeaders || {})) {
          if (k.toLowerCase() === want) return rawHeaders[k];
        }
        return null;
      }
    },
    text: async () => asText(),
    body: rawBody,
    json: async () => {
      if (rawBody && typeof rawBody === 'object' && !Buffer.isBuffer(rawBody)) return rawBody;
      try { return JSON.parse(asText()); } catch (e) { return {}; }
    }
  };
}

const inputItem = $input.first()?.json || {};
