try { initData = $('Init YouTube Resumable Upload').first()?.json || {}; } catch(e) {}

let videoId = inputItem.id || inputItem.uploadId;
const accessToken = initData.accessToken || inputItem.accessToken;
const title = initData.title || inputItem.title || 'Viral YouTube Short';
const bytes = Number(initData.fileSize || inputItem.fileSize || 0);
const mimeType = initData.mimeType || 'video/mp4';
const channelTitle = initData.channelTitle || inputItem.channelTitle || '';
const srcUrl = initData.srcUrl || '';

// Auto-Recovery: If videoId not directly returned, query Google Resumable Upload Status (handles 308 or socket-end)
if (!videoId && initData.uploadUrl) {
  try {
    const statusRes = await httpFetch(initData.uploadUrl, {
      method: 'PUT',
      headers: {
        'Content-Length': '0',
        'Content-Range': 'bytes */' + (bytes > 0 ? String(bytes) : '*')
      },
      timeout: 15000
    });

    if (statusRes.status === 200 || statusRes.status === 201) {
      const vidJson = await statusRes.json();
      if (vidJson.id) videoId = vidJson.id;
    } else if (statusRes.status === 308 && srcUrl && bytes > 0) {
      const rangeHeader = statusRes.headers.get('range');
      if (rangeHeader) {
        const m = rangeHeader.match(/bytes=0-(\d+)/);
        if (m) {
          const lastByte = parseInt(m[1], 10);
          const nextByte = lastByte + 1;
          const missingBytes = bytes - nextByte;
          if (missingBytes > 0 && missingBytes <= 50 * 1024 * 1024) {
            const sliceRes = await httpFetch(srcUrl, {
              method: 'GET',
              headers: { 'Range': 'bytes=' + nextByte + '-' + (bytes - 1) },
              timeout: 30000
            });
