                method: 'PUT',
                headers: {
                  'Content-Length': String(tailBuffer.length),
                  'Content-Range': 'bytes ' + nextByte + '-' + (bytes - 1) + '/' + bytes
                },
                body: tailBuffer,
                timeout: 60000
              });
              if (finalPutRes.status === 200 || finalPutRes.status === 201) {
                const finalVid = await finalPutRes.json();
                if (finalVid.id) videoId = finalVid.id;
              }
            }
          }
        }
      }
    }
  } catch (recoverErr) {
    console.warn('[Dynamic User YouTube Upload] Recovery query notice:', recoverErr.message);
  }
}

if (!videoId) {
  const errDesc = inputItem.error?.message || JSON.stringify(inputItem) || 'YouTube Stream Upload Failed';
  return [{
    json: {
      success: false,
      uploadId: null,
      id: null,
      title: title,
      url: '',
      channelTitle: channelTitle,
      userUploaded: false,
      bytesUploaded: 0,
