      ytUploadStatus: 'failed',
      ytProcessingStatus: 'failed',
      ytFailureReason: errDesc,
      uploadStatus: 'FAILED',
      uploadError: errDesc
    }
  }];
}

let ytUploadStatus = 'uploaded';
let ytProcessingStatus = 'processing';
let ytFailureReason = null;
let ytRejectionReason = null;

if (accessToken && videoId) {
  try {
    const vRes = await httpFetch('https://www.googleapis.com/youtube/v3/videos?part=status,processingDetails&id=' + videoId, {
      method: 'GET',
      headers: { 'Authorization': 'Bearer ' + accessToken },
