const rawHook = $('Website Webhook Trigger').first().json || {};
const payload = rawHook.body || rawHook;
const showId = String(payload.showId || 'ISL-001').trim();
const userId = String(payload.userId || '').trim();
const storyMode = String(payload.storyMode || 'random').trim().toLowerCase();
const seasonTag = String(payload.seasonTag || '').trim().toLowerCase();
const seriesIdIn = String(payload.seriesId || '').trim();
const customTopic = String(payload.customEpisodeTopic || payload.prompt || '').trim();
const channelId = String(payload.userYouTubeChannelId || '');
const threadId = String(payload.threadId || '');
const characterImages = payload.characterImages || {};
const STALE_MS = 3 * 60 * 60 * 1000;
const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();

if (showId !== 'ISL-001') { throw new Error('Unknown showId: ' + showId); }
if (!userId) { throw new Error('userId is required.'); }

const randomRows = $('Read Library Stories').all().map(i => i.json).filter(e => e && e.story_id);
const partRows = $('Read Series Parts').all().map(i => i.json).filter(e => e && e.series_id);
const seriesRows = $('Read Library Series').all().map(i => i.json).filter(e => e && e.series_id);
const usageRows = $('Read Library Usage').all().map(i => i.json).filter(u => u && u.user_id);

const isReady = (e) => { const st = String(e.status || '').trim().toLowerCase(); return st === '' || st === 'ready'; };
const randoms = randomRows.filter(e => e.show_id === showId && String(e.status || '').toLowerCase() === 'ready').map(e => ({ story_id: String(e.story_id), season_tag: String(e.season_tag || '').toLowerCase(), row: e }));
const parts = partRows.filter(isReady).map(e => ({ story_id: String(e.story_id || ''), series_id: String(e.series_id), part_no: Number(e.part_no), row: e }));
const seriesList = seriesRows.filter(c => c.show_id === showId).map(c => ({ series_id: String(c.series_id), row: c }));
const usage = usageRows.map(u => ({ user_id: String(u.user_id), story_id: String(u.story_id || ''), series_id: String(u.series_id || ''), part_no: Number(u.series_part || u.part_no || 0), status: String(u.status || ''), claimed_at: u.claimed_at || '' }));

const isConsumed = (u) => {
  if (u.user_id !== userId) return false;
  if (u.status === 'done') return true;
  if (u.status === 'claimed') {
    const t = Date.parse(u.claimed_at || '');
    return isNaN(t) ? true : (nowMs - t) < STALE_MS;
  }
  return false;
};
const usedStories = new Set(usage.filter(isConsumed).map(u => u.story_id));
const randomPart = Math.floor(Math.random() * 1000000);

let story = null;
let pickMode = '';
let seriesRow = null;
let partNo = 0;
let storyId = '';

if (storyMode === 'custom') {
  if (!customTopic) { throw new Error('Custom mode needs a topic.'); }
  pickMode = 'islamic_custom';
  storyId = 'CUSTOM-' + nowMs + '-' + randomPart;
  story = { story_id: storyId, show_id: showId, category: 'custom', title_hi: customTopic.slice(0, 80), hook_hi: '', beat1_hi: '', beat2_hi: '', beat3_hi: '', beat4_hi: '', beat5_hi: '', cliffhanger_hi: '', emotion: '', source_note: 'user custom topic', custom_topic: customTopic };
} else if (storyMode === 'series') {
  pickMode = 'islamic_series';
  const sid = seriesIdIn || (seriesList[0] ? seriesList[0].series_id : '');
  if (!sid) { throw new Error('No series available.'); }
  const doneNos = usage.filter(u => u.user_id === userId && u.series_id === sid && u.status === 'done').map(u => u.part_no);
  const nextNo = doneNos.length ? Math.max(...doneNos) + 1 : 1;
  const hit = parts.find(p => p.series_id === sid && p.part_no === nextNo);
  if (!hit) { throw new Error('Series ' + sid + ' has no part ' + nextNo + ' for this user.'); }
  story = hit.row;
  storyId = hit.story_id || ('ISL-S-' + sid + '-' + nextNo);
  partNo = nextNo;
  const sRow = seriesList.find(c => c.series_id === sid);
  seriesRow = sRow ? sRow.row : null;
} else {
  if (storyMode === 'season' && !seasonTag) { throw new Error('Season mode needs seasonTag.'); }
  const pool = randoms.filter(e => !usedStories.has(e.story_id) && (storyMode !== 'season' || e.season_tag === seasonTag));
  if (!pool.length) { throw new Error('No unused stories left for this selection.'); }
  const chosen = pool[Math.floor(Math.random() * pool.length)];
  story = chosen.row;
  storyId = chosen.story_id;
  pickMode = storyMode === 'season' ? 'islamic_season' : 'islamic_random';
}

return [{ json: { claimNeeded: true, pickMode: pickMode, showId: showId, storyMode: storyMode, partNo: partNo, libraryStory: story, usageRow: { usage_id: 'use_' + nowMs + '_' + randomPart, user_id: userId, story_id: storyId, series_id: seriesRow ? String(seriesRow.series_id) : (storyMode === 'series' ? seriesIdIn : ''), part_no: String(partNo), mode: storyMode, status: 'claimed', video_url: '', channel_id: channelId, claimed_at: nowIso, finished_at: '', run_id: threadId, template_id: 'islamic-stories-hindi' }, seriesRow: seriesRow, characterImages: characterImages } }];

