const LUM = 'Garment-first: first describe the full period outfit and headwear in rich detail, with full-length sleeves covering the arms down to the wrists. Then render ONLY the exposed head, face, neck and hands as a single continuous 3D volumetric entity of static, solid, pure-white divine light, 100% opaque and completely featureless, with no visible eyes, mouth, skin or neck contours beneath, from the first frame to the last. The light merges into the collar and cuffs with crisp boundaries and gives zero light spill onto the outfit.';
const sacred = brief.isSacredFigure === true;
const faceRule = row && row.face_rule_en ? String(row.face_rule_en).trim() : (sacred ? LUM : '');
const anchorImagePrompt = 'Cinematic, photorealistic full-length portrait of ' + who + ', ' + era + '. ' + outfit + ' ' + faceRule + ' Natural relaxed standing pose with a natural body angle, full figure visible from head to feet, camera at eye level, rich fabric texture, embroidery and jewellery detail, grand and distinctive costume. Period-accurate setting with soft natural light, 9:16 vertical. No back view, no figure seen from behind, no text, no logos, no watermark.';
