const staticData = $getWorkflowStaticData('global');
const keys = $('Config: Kie Image Master').first().json.keys || [];
const total = keys.length;
const err = $input.first().json || {};
const prev = $('Rotate Kie Image Key').last().json || {};
const isRateLimit = err.code == 429 || err.code == '429' || String(err.msg || '').toLowerCase().includes('frequency');
if (isRateLimit) { await new Promise(r => setTimeout(r, 5000)); }
staticData.kieImageAttempts = (staticData.kieImageAttempts || 0) + 1;
staticData.kieImageKeyIndex = (staticData.kieImageKeyIndex || 0) + 1;
const exhausted = total === 0 || staticData.kieImageAttempts >= total;
if (exhausted) { staticData.kieImageAttempts = 0; staticData.kieImageKeyIndex = 0; }
return [{ json: { anchorImagePrompt: prev.anchorImagePrompt || '', script: prev.script || {}, allKeysExhausted: exhausted } }];

// Validate Critic Scenes (Primary)
// Checks: exactly 5 sequential scenes, narration length 220 to 280 characters, SEO youtubeDescription length 800 to 1200 characters, no non-Islamic greetings or words, and no back-view shots.
// Scientists, science topics and historical or non-Islamic settings are allowed in Islamic stories.
const EXPECTED = 5;
const MIN_LEN = 220;
const MAX_LEN = 280;
const DESC_MIN = 800;
const DESC_MAX = 1200;
const BLOCKED = /नमस्कार|प्रणाम|ॐ|भगवान|ईश्वर|मंदिर|पूजा|आरती|हरि|गुरु|(^|[ ,।!?])जय([ ,।!?]|$)|(^|[ ,।!?])राम([ ,।!?]|$)/;
const item = $input.first().json || {};
if (item.criticVerdict !== 'approved') { return [{ json: item }]; }
const scenes = Array.isArray(item.scenes) ? item.scenes : [];
const nums = scenes.map(s => Number(s.sceneNumber));
const seqOk = scenes.length === EXPECTED && nums.every((n, i) => n === i + 1);
const lens = scenes.map(s => String(s.voiceoverText || '').length);
const lenOk = lens.length > 0 && lens.every(l => l >= MIN_LEN && l <= MAX_LEN);
const descLen = String(item.youtubeDescription || '').length;
const descOk = descLen >= DESC_MIN && descLen <= DESC_MAX;
const badWords = scenes.filter(s => BLOCKED.test(String(s.voiceoverText || '')));
const BACK_WORDS = ['from behind', 'back view', 'back of the', 'turned away', 'facing away', 'back to camera', 'back to the camera', 'seen from behind', 'from the back', 'rear view', 'rear shot'];
const backScenes = scenes.filter(s => { const l = String(s.videoPrompt || '').toLowerCase(); return BACK_WORDS.some(w => l.indexOf(w) !== -1); });
if (seqOk && descOk && badWords.length === 0 && backScenes.length === 0 && lenOk) { return [{ json: item }]; }
let reason;
if (!seqOk) {
  reason = 'Scene check failed: expected ' + EXPECTED + ' sequential scenes, got ' + scenes.length + ' (sceneNumbers: ' + nums.join(',') + ')';
} else if (!descOk) {
  reason = 'SEO youtubeDescription is ' + descLen + ' characters; it must be ' + DESC_MIN + ' to ' + DESC_MAX + ' characters, with the main keyword in the first line, three paragraphs, a comment and subscribe call, and 10 to 12 hashtags.';
} else if (badWords.length > 0) {
  reason = 'Non-Islamic greeting or word found in narration of scene(s) ' + badWords.map(s => s.sceneNumber).join(',') + '. Use only Islamic greetings and words.';
} else if (backScenes.length > 0) {
  reason = 'Back-view shot found in scene(s) ' + backScenes.map(s => s.sceneNumber).join(',') + '. Remove every shot where the character is seen from behind or turned away; show the figure from a natural angle.';
} else {
  reason = 'Narration length out of range (' + MIN_LEN + '-' + MAX_LEN + ' characters): ' + lens.join(',');
}
return [{ json: { ...item, criticVerdict: 'rejected', criticError: reason } }];

// Validate Critic Scenes (Backup)
// Checks: exactly 5 sequential scenes, narration length 220 to 280 characters, SEO youtubeDescription length 800 to 1200 characters, no non-Islamic greetings or words, and no back-view shots.
// Scientists, science topics and historical or non-Islamic settings are allowed in Islamic stories.
const EXPECTED = 5;
const MIN_LEN = 220;
const MAX_LEN = 280;
const DESC_MIN = 800;
const DESC_MAX = 1200;
const BLOCKED = /नमस्कार|प्रणाम|ॐ|भगवान|ईश्वर|मंदिर|पूजा|आरती|हरि|गुरु|(^|[ ,।!?])जय([ ,।!?]|$)|(^|[ ,।!?])राम([ ,।!?]|$)/;
const item = $input.first().json || {};
if (item.criticVerdict !== 'approved') { return [{ json: item }]; }
const scenes = Array.isArray(item.scenes) ? item.scenes : [];
const nums = scenes.map(s => Number(s.sceneNumber));
const seqOk = scenes.length === EXPECTED && nums.every((n, i) => n === i + 1);
const lens = scenes.map(s => String(s.voiceoverText || '').length);
const lenOk = lens.length > 0 && lens.every(l => l >= MIN_LEN && l <= MAX_LEN);
const descLen = String(item.youtubeDescription || '').length;
const descOk = descLen >= DESC_MIN && descLen <= DESC_MAX;
const badWords = scenes.filter(s => BLOCKED.test(String(s.voiceoverText || '')));
const BACK_WORDS = ['from behind', 'back view', 'back of the', 'turned away', 'facing away', 'back to camera', 'back to the camera', 'seen from behind', 'from the back', 'rear view', 'rear shot'];
const backScenes = scenes.filter(s => { const l = String(s.videoPrompt || '').toLowerCase(); return BACK_WORDS.some(w => l.indexOf(w) !== -1); });
if (seqOk && descOk && badWords.length === 0 && backScenes.length === 0 && lenOk) { return [{ json: item }]; }
let reason;
if (!seqOk) {
  reason = 'Scene check failed: expected ' + EXPECTED + ' sequential scenes, got ' + scenes.length + ' (sceneNumbers: ' + nums.join(',') + ')';
} else if (!descOk) {
  reason = 'SEO youtubeDescription is ' + descLen + ' characters; it must be ' + DESC_MIN + ' to ' + DESC_MAX + ' characters, with the main keyword in the first line, three paragraphs, a comment and subscribe call, and 10 to 12 hashtags.';
} else if (badWords.length > 0) {
  reason = 'Non-Islamic greeting or word found in narration of scene(s) ' + badWords.map(s => s.sceneNumber).join(',') + '. Use only Islamic greetings and words.';
} else if (backScenes.length > 0) {
  reason = 'Back-view shot found in scene(s) ' + backScenes.map(s => s.sceneNumber).join(',') + '. Remove every shot where the character is seen from behind or turned away; show the figure from a natural angle.';
} else {
  reason = 'Narration length out of range (' + MIN_LEN + '-' + MAX_LEN + ' characters): ' + lens.join(',');
}
return [{ json: { ...item, criticVerdict: 'rejected', criticError: reason } }];

// Per-run reset: clears counters and history left by previous runs so static data cannot keep growing.
const staticData = $getWorkflowStaticData('global');
const EXPECTED = 5;
staticData.fruitCriticAttemptsPrimary = 0;
staticData.fruitCriticAttemptsBackup = 0;
staticData.fruitCriticRetriesPrimary = 0;
staticData.fruitCriticRetriesBackup = 0;
delete staticData.fruitSavedScriptPrimary;
delete staticData.fruitSavedScriptBackup;
staticData.fruitUseBackupLlm = false;
staticData.fruitPrimaryLlmAttempts = 0;
staticData.fruitBackupLlmAttempts = 0;
staticData.fruitParseRetries = 0;
// Topic and character history grows on every run (written by Parse AI JSON and Handle Backup LLM Success). Story repeats are already prevented by the sheet usage tracking, so this history is cleared each run.
staticData.fruitLastTopics = [];
staticData.fruitLastCharacters = [];
for (let n = 1; n <= EXPECTED; n++) {
  staticData['fruitVideoAttempts_' + n] = 0;
  staticData['fruitUseBackupVideo_' + n] = false;
  staticData['fruitBackupVideoAttempts_' + n] = 0;
  delete staticData['savedVideoPrompt_' + n];
}
return $input.all();

// Find Character
// Matches a Characters-tab row to this story by finding the character's core name in the story text. Works for any story: no hardcoded names.
const claim = $('Claim Library Usage').first().json || {};
const chars = $input.all().map(i => i.json).filter(r => r && r.character_name_hi && String(r.status || '').trim().toLowerCase() !== 'disabled');
const s = (() => { try { return $('Pick Library Story').first().json.libraryStory || {}; } catch (e) { return {}; } })();
const storyText = [s.title_hi, s.hook_hi, s.beat1_hi, s.beat2_hi, s.beat3_hi, s.beat4_hi, s.beat5_hi, s.cliffhanger_hi].filter(Boolean).join(' ');
const HON = /हज़रत|अलैहिस्सलाम|अलैहि|रज़ियल्लाहु अन्हुम|रज़ियल्लाहु अन्हु|रज़ियल्लाहु अन्हा|रहमतुल्लाह|हजरत|अलैहिस्सलाम/g;
let best = null;
let bestLen = 0;
for (const r of chars) {
  const core = String(r.character_name_hi).replace(HON, '').split(' ').filter(Boolean).join(' ');
  if (core.length >= 3 && storyText.includes(core) && core.length > bestLen) {
    best = r;
    bestLen = core.length;
  }
}
return [{ json: { ...claim, characterRow: best, characterMatched: best ? best.character_name_hi : '' } }];

// Normalize Critic Output
// The model sometimes returns a videoPrompt or voiceoverText as a list of shot strings. Join each list into one string before the parser reads it.
function fixVal(v) {
  if (Array.isArray(v)) return v.map(x => (typeof x === 'string' ? x : JSON.stringify(x))).join(' ');
  return v;
}
const item = $input.first().json;
try {
  const content = item.choices[0].message.content;
  const obj = JSON.parse(content);
  if (obj && Array.isArray(obj.scenes)) {
    obj.scenes = obj.scenes.map(s => ({ ...s, videoPrompt: fixVal(s.videoPrompt), voiceoverText: fixVal(s.voiceoverText) }));
    item.choices[0].message.content = JSON.stringify(obj);
  }
} catch (e) {
  // leave the response unchanged; the parser handles it as before
}
return [{ json: item }];

// Normalize Critic Output
// The model sometimes returns a videoPrompt or voiceoverText as a list of shot strings. Join each list into one string before the parser reads it.
function fixVal(v) {
  if (Array.isArray(v)) return v.map(x => (typeof x === 'string' ? x : JSON.stringify(x))).join(' ');
  return v;
}
const item = $input.first().json;
try {
  const content = item.choices[0].message.content;
  const obj = JSON.parse(content);
  if (obj && Array.isArray(obj.scenes)) {
    obj.scenes = obj.scenes.map(s => ({ ...s, videoPrompt: fixVal(s.videoPrompt), voiceoverText: fixVal(s.voiceoverText) }));
    item.choices[0].message.content = JSON.stringify(obj);
  }
} catch (e) {
  // leave the response unchanged; the parser handles it as before
}
return [{ json: item }];

// Prepare Repairs
// After the critic's retries: scenes outside 220 to 280 characters, and a youtube description outside 800 to 1200 characters, each get a separate short repair call.
// Keys rotate through the critic key pool. If nothing needs repair, the script passes straight through.
const NL = String.fromCharCode(10);
const staticData = $getWorkflowStaticData('global');
const MIN_LEN = 220;
const MAX_LEN = 280;
const DESC_MIN = 800;
const DESC_MAX = 1200;
const script = $input.first().json || {};
const scenes = Array.isArray(script.scenes) ? script.scenes : [];
const needs = scenes.map((s, i) => ({ sceneNumber: Number(s.sceneNumber) || (i + 1), text: String(s.voiceoverText || '') }))
  .filter(x => x.text.length < MIN_LEN || x.text.length > MAX_LEN);
const desc = String(script.youtubeDescription || '');
const descBad = desc.length < DESC_MIN || desc.length > DESC_MAX;
if (script.criticVerdict !== 'approved' || (needs.length === 0 && !descBad)) {
  return [{ json: { noRepair: true, script: script, criticVerdict: script.criticVerdict } }];
}
let cfg = {};
try { cfg = $('Config: Critic LLM Master (Primary)').first().json || {}; } catch (e) {
  try { cfg = $('Config: Critic LLM Master (Backup)').first().json || {}; } catch (e2) { cfg = {}; }
}
const keys = Array.isArray(cfg.keys) ? cfg.keys : [];
let keyIdx = Number(staticData.fruitRepairKeyIndex || 0);
const out = needs.map(x => {
  const usedKey = keys.length ? keys[keyIdx % keys.length] : '';
  keyIdx += 1;
  const target = x.text.length < MIN_LEN
    ? 'The original is too short. Add concrete detail from the same events. The result must be at least 230 and at most 270 characters, aiming for about 250.'
    : 'The original is too long. Shorten it by removing filler, keeping every fact. The result must be at least 230 and at most 270 characters, aiming for about 250.';
  const messages = [
    { role: 'system', content: 'You rewrite one scene of narration for an Islamic stories YouTube Short in Hindi. Keep the same events, facts, names and tone. Use only Devanagari Hindi with full honorifics and Islamic vocabulary. Do not add new events or figures. Output JSON only, in this form: {"voiceoverText": "..."}' },
    { role: 'user', content: 'ORIGINAL SCENE (' + x.text.length + ' characters):' + NL + x.text + NL + NL + 'TARGET: ' + target + NL + 'Return only the JSON.' }
  ];
  return { json: { noRepair: false, kind: 'scene', sceneNumber: x.sceneNumber, originalText: x.text, usedKey: usedKey, messages: messages, script: script, criticVerdict: script.criticVerdict } };
});
if (descBad) {
  const usedKey = keys.length ? keys[keyIdx % keys.length] : '';
  keyIdx += 1;
  const target = desc.length < DESC_MIN
    ? 'The description is too short. Expand it to at least 800 and at most 1200 characters, aiming for about 1000.'
    : 'The description is too long. Shorten it to at least 800 and at most 1200 characters, aiming for about 1000.';
  const messages = [
    { role: 'system', content: 'You write the YouTube description for an Islamic stories YouTube Short in Hindi. Use Devanagari Hindi and Islamic vocabulary only. The first line holds the main keyword of the story. Then three short paragraphs about the story and its lesson. Then a comment call and a subscribe call. Then 10 to 12 hashtags. Output JSON only, in this form: {"youtubeDescription": "..."}' },
    { role: 'user', content: 'STORY TITLE: ' + String(script.title || '') + NL + 'ORIGINAL DESCRIPTION (' + desc.length + ' characters):' + NL + desc + NL + NL + 'TARGET: ' + target + NL + 'Return only the JSON.' }
  ];
  out.push({ json: { noRepair: false, kind: 'description', sceneNumber: 0, originalText: desc, usedKey: usedKey, messages: messages, script: script, criticVerdict: script.criticVerdict } });
}
staticData.fruitRepairKeyIndex = keyIdx;
return out;

// Merge Repaired Scenes
// Puts repaired narration and the repaired youtube description back into the script. A repair that still misses its window is kept as the closest version and recorded.
// If a repair call failed, the original text is kept. The run never stops on length.
const prep = $('Prepare Repairs').first().json || {};
const script = prep.script || {};
const scenes = Array.isArray(script.scenes) ? script.scenes.map(s => ({ ...s })) : [];
const MIN_LEN = 220;
const MAX_LEN = 280;
const DESC_MIN = 800;
const DESC_MAX = 1200;
const repairs = $('Prepare Repairs').all().map(i => i.json).filter(r => r && r.noRepair === false);
const responses = $input.all().map(i => i.json || {});
const report = [];
let youtubeDescription = script.youtubeDescription || '';
function trimToMax(text, max) {
  const t = String(text || '').trim();
  if (t.length <= max) return t;
  const sentences = t.replace(/[।.?!]/g, m => m + '|||').split('|||').map(s => s.trim()).filter(Boolean);
  let out = sentences.join(' ');
  while (out.length > max && sentences.length > 1) { sentences.pop(); out = sentences.join(' '); }
  if (out.length > max) out = out.slice(0, max).trim();
  return out;
}
repairs.forEach((r, i) => {
  let candidate = null;
  try {
    const obj = JSON.parse(responses[i].choices[0].message.content);
    if (r.kind === 'description') {
      if (obj && typeof obj.youtubeDescription === 'string' && obj.youtubeDescription.trim()) candidate = obj.youtubeDescription.trim();
    } else if (obj && typeof obj.voiceoverText === 'string' && obj.voiceoverText.trim()) {
      candidate = obj.voiceoverText.trim();
    }
  } catch (e) { candidate = null; }
  if (r.kind === 'description') {
    let d = candidate || r.originalText;
    if (d.length > DESC_MAX) d = trimToMax(d, DESC_MAX);
    youtubeDescription = d;
    report.push({ item: 'description', before: r.originalText.length, after: d.length, repaired: !!candidate, inWindow: d.length >= DESC_MIN && d.length <= DESC_MAX });
    return;
  }
  const idx = scenes.findIndex(s => Number(s.sceneNumber) === Number(r.sceneNumber));
  if (idx < 0) return;
  let text = candidate || r.originalText;
  if (text.length > MAX_LEN) text = trimToMax(text, MAX_LEN);
  scenes[idx] = { ...scenes[idx], voiceoverText: text };
  report.push({ item: 'scene ' + r.sceneNumber, before: r.originalText.length, after: text.length, repaired: !!candidate, inWindow: text.length >= MIN_LEN && text.length <= MAX_LEN });
});
const verdict = prep.criticVerdict === 'failed' ? 'failed' : 'approved';
return [{ json: { ...script, scenes: scenes, youtubeDescription: youtubeDescription, criticVerdict: verdict, lengthRepair: report } }];
